from decimal import Decimal, InvalidOperation


def _check_groups(int_part: str, sep: str) -> str:
    groups = int_part.split(sep)
    if not (1 <= len(groups[0]) <= 3) or not groups[0].isdigit():
        raise ValueError(f"bad thousands grouping: {int_part!r}")
    for g in groups[1:]:
        if len(g) != 3 or not g.isdigit():
            raise ValueError(f"bad thousands grouping: {int_part!r}")
    return "".join(groups)


def _validate_space_grouping(raw: str, nospace: str) -> None:
    # Only called when raw contains space / NBSP.
    # Validate space thousands grouping in the integer part, without
    # confusing it with later ./, decimal/thousands handling.
    has_dot = "." in nospace
    has_comma = "," in nospace
    dec_sep = None
    if has_dot and has_comma:
        dec_sep = "." if nospace.rfind(".") > nospace.rfind(",") else ","
    elif has_comma:
        if nospace.count(",") == 1:
            dec_sep = ","
    elif has_dot:
        if nospace.count(".") == 1:
            dec_sep = "."
    if dec_sep is not None:
        pos = raw.rfind(dec_sep)
        if pos == -1:
            integer_raw = raw
        else:
            integer_raw = raw[:pos]
            frac_raw = raw[pos + 1:]
            if " " in frac_raw or "\u00a0" in frac_raw:
                raise ValueError(f"bad space grouping with decimal part: {raw!r}")
    else:
        integer_raw = raw
    tmp = integer_raw.replace("\u00a0", " ")
    # Remove ./, so space-group lengths are not confused with later handling.
    # Later ./, grouping is still validated separately after space removal.
    tmp_no_sep = tmp.replace(".", "").replace(",", "")
    parts = tmp_no_sep.split(" ")
    # Any empty part means leading/trailing/consecutive spaces or space
    # adjacent to a ./, separator.
    if any(p == "" for p in parts):
        raise ValueError(f"bad space grouping: {raw!r}")
    # If integer part has no spaces, spaces were in fractional part
    # (already rejected) or otherwise malformed.
    if " " not in tmp:
        # No space grouping to validate in integer part; fractional check
        # above already handled spaces in fraction. If we are here with
        # spaces in raw but none in integer, it must have been fractional.
        raise ValueError(f"bad space grouping: {raw!r}")
    if not (1 <= len(parts[0]) <= 3):
        raise ValueError(f"bad space grouping: {raw!r}")
    for g in parts[1:]:
        if len(g) != 3:
            raise ValueError(f"bad space grouping: {raw!r}")
    for g in parts:
        if not g.isdigit():
            raise ValueError(f"bad space grouping: {raw!r}")


def parse_number(text: str) -> Decimal:
    if not isinstance(text, str):
        raise ValueError("text must be a string")
    s = text.strip(" \t\u00a0")
    if not s:
        raise ValueError("empty input")
    negative = False
    if s.startswith("(") or s.endswith(")"):
        if not (s.startswith("(") and s.endswith(")") and len(s) >= 2):
            raise ValueError("unbalanced parentheses")
        inner = s[1:-1].strip(" \t\u00a0")
        if inner.startswith(("+", "-")):
            raise ValueError("sign cannot be combined with parentheses")
        negative = True
        s = inner
    elif s.startswith(("+", "-")):
        negative = s[0] == "-"
        s = s[1:]
    if not s:
        raise ValueError("no digits")
    if s.startswith(("+", "-")) or "(" in s or ")" in s:
        raise ValueError("misplaced sign or parenthesis")
    # Validate space thousands grouping before removing spaces.
    if " " in s or "\u00a0" in s:
        nospace = s.replace(" ", "").replace("\u00a0", "")
        _validate_space_grouping(s, nospace)
    s = s.replace(" ", "").replace("\u00a0", "")
    if not s or any(c not in "0123456789.," for c in s):
        raise ValueError(f"invalid characters in {text!r}")
    if not any(c.isdigit() for c in s):
        raise ValueError("no digits")
    has_dot = "." in s
    has_comma = "," in s
    if has_dot and has_comma:
        if s.rfind(".") > s.rfind(","):
            dec_sep, thou_sep = ".", ","
        else:
            dec_sep, thou_sep = ",", "."
        int_part, _, frac_part = s.rpartition(dec_sep)
        if dec_sep in int_part:
            raise ValueError("multiple decimal separators")
        if not int_part or not frac_part or not frac_part.isdigit():
            raise ValueError("bad decimal part")
        int_digits = _check_groups(int_part, thou_sep) if thou_sep in int_part else int_part
        if not int_digits.isdigit():
            raise ValueError("bad integer part")
        normalized = f"{int_digits}.{frac_part}"
    elif has_comma:
        if s.count(",") > 1:
            int_digits = _check_groups(s, ",")
            normalized = int_digits
        else:
            int_part, _, frac_part = s.partition(",")
            if not int_part or not frac_part or not int_part.isdigit() or not frac_part.isdigit():
                raise ValueError("bad comma decimal")
            normalized = f"{int_part}.{frac_part}"
    elif has_dot:
        if s.count(".") > 1:
            int_digits = _check_groups(s, ".")
            normalized = int_digits
        else:
            int_part, _, frac_part = s.partition(".")
            if not int_part or not frac_part or not int_part.isdigit() or not frac_part.isdigit():
                raise ValueError("bad dot decimal")
            normalized = f"{int_part}.{frac_part}"
    else:
        if not s.isdigit():
            raise ValueError("bad integer")
        normalized = s
    try:
        value = Decimal(normalized)
    except InvalidOperation:
        raise ValueError(f"invalid number: {text!r}") from None
    return -value if negative else value

