from decimal import Decimal, InvalidOperation


def split_installments(total: str, n: int) -> list[Decimal]:
    if isinstance(n, bool) or not isinstance(n, int):
        raise ValueError("n must be an integer")
    if n < 1:
        raise ValueError("n must be >= 1")
    if not isinstance(total, str):
        raise ValueError("total must be a string")
    try:
        amount = Decimal(total)
    except (InvalidOperation, ValueError):
        raise ValueError(f"invalid total: {total!r}") from None
    if not amount.is_finite():
        raise ValueError("total must be finite")
    if amount < 0:
        raise ValueError("total must be >= 0")
    # Precision limit is on the supplied representation: exponent must be >= -2.
    # This rejects trailing-zero extras like "10.000" or "1.230".
    if amount.as_tuple().exponent < -2:
        raise ValueError("total must have at most 2 decimal places")
    # Exact cents without going through a precision-limited quantize/multiply.
    # scaleb is exact; since exponent >= -2, scaleb(2) is integral.
    try:
        cents_dec = amount.scaleb(2)
    except (InvalidOperation, ValueError):
        raise ValueError("total must have at most 2 decimal places") from None
    try:
        cents = int(cents_dec.to_integral_value())
    except (InvalidOperation, ValueError):
        raise ValueError("total must have at most 2 decimal places") from None
    # to_integral_value uses rounding; ensure exactness (no fractional cents).
    if Decimal(cents) != cents_dec:
        raise ValueError("total must have at most 2 decimal places")
    base, remainder = divmod(cents, n)
    parts = []
    for i in range(n):
        part_cents = base + (1 if i < remainder else 0)
        # Exact construction with exponent -2, avoiding quantize precision limits.
        parts.append(Decimal(part_cents).scaleb(-2))
    return parts
